/bin/zsh -lc "/Users/omar/.codex/skills/openpencil/scripts/openpencil-cli.sh board build --fresh-context --runtime-instance-id 'local-authority:local-authority-f06b17af-2b12-4b51-8e75-49506e084910' --workspace-id 'workspace-44c2b737-ada8-4e45-b8d9-1d30aadf4fdc' --document-id 'document-1b633407-6552-4f35-a64b-7ac3899a306d' --content-document-id 'document-1b633407-6552-4f35-a64b-7ac3899a306d' --page-id '0:2602' --request-id 'ocean-cleanup-portfolio-2m-20260730-v1' --intent 'Build a polished editable board brief comparing three ocean-cleanup programs and recommending allocation of a two million dollar twelve-month portfolio, with impact, cost, execution risk, explicit decision rules, and three first-week actions.' --plan-file - --json <<'JSON'
{
  \"contract\": \"board-build-plan/v1\",
  \"artifacts\": [
    {
      \"alias\": \"title\",
      \"recipe\": {
        \"kind\": \"native_text\",
        \"text\": \"OCEAN CLEANUP • "'$2M PORTFOLIO DECISION'"\\nBoard brief | 12-month deployment | Decision-ready working draft\",
        \"placement\": {\"target\": {\"kind\": \"auto\"}}
      }
    },
    {
      \"alias\": \"river\",
      \"recipe\": {
        \"kind\": \"native_card\",
        \"title\": \"01 — River interception\",
        \"body\": \"ALLOCATION  "'$900k • 45%'"\\nIMPACT  350–550 t prevented before ocean entry\\nPLANNING COST  "'$1.6k–$2.6k per tonne'"\\nEXECUTION RISK  MEDIUM\\n\\nWHY IT EARNS A PLACE\\nHigh-volume capture at repeatable hotspots; strong weighing and auditability.\\n\\nWATCH\\nPermits, flood-season uptime, and downstream disposal capacity.\"
      }
    },
    {
      \"alias\": \"gear\",
      \"recipe\": {
        \"kind\": \"native_card\",
        \"title\": \"02 — Ghost-gear recovery\",
        \"body\": \"ALLOCATION  "'$600k • 30%'"\\nIMPACT  130–220 t of nets and gear recovered\\nPLANNING COST  "'$2.7k–$4.6k per tonne'"\\nEXECUTION RISK  MEDIUM–HIGH\\n\\nWHY IT EARNS A PLACE\\nLower tonnage, but outsized benefit for wildlife, reefs, and navigation.\\n\\nWATCH\\nWeather windows, vessel safety, gear localization, and recycling outlets.\"
      }
    },
    {
      \"alias\": \"community\",
      \"recipe\": {
        \"kind\": \"native_card\",
        \"title\": \"03 — Coastal collection + recycling\",
        \"body\": \"ALLOCATION  "'$500k • 25%'"\\nIMPACT  180–300 t collected or prevented\\nPLANNING COST  "'$1.7k–$2.8k per tonne'"\\nEXECUTION RISK  MEDIUM\\n\\nWHY IT EARNS A PLACE\\nFills leakage gaps while building local jobs, partners, and durable collection habits.\\n\\nWATCH\\nContamination, buyer demand, worker safeguards, and double-counting.\"
      }
    },
    {
      \"alias\": \"mix\",
      \"recipe\": {
        \"kind\": \"native_card\",
        \"title\": \"Recommended mix — fund all three\",
        \"body\": \""'$900k  River interception'"\\n"'$600k  Ghost-gear recovery'"\\n"'$500k  Coastal collection + recycling'"\\n\\nPORTFOLIO OUTLOOK\\n660–1,070 t prevented or recovered in year one\\nImplied blended cost: "'$1.9k–$3.0k per tonne'"\\n\\nRATIONALE\\nUse river systems as the volume engine; preserve targeted ecological value and community durability through deliberate diversification.\"
      }
    },
    {
      \"alias\": \"rules\",
      \"recipe\": {
        \"kind\": \"native_card\",
        \"title\": \"Decision rules — approve with gates\",
        \"body\": \"1  AWARD GATE\\nBaseline, permits, safety plan, monthly weights, and traceable end destination required.\\n\\n2  COST CEILINGS\\nRiver "'$2.8k/t • Gear $5.0k/t • Community $3.0k/t.'"\\n\\n3  RELEASE GATE\\nStage payments; retain 20% inside each award until verified milestones.\\n\\n4  90-DAY SHIFT TRIGGER\\nReallocate if run-rate <75%, unit cost >125% of ceiling, two reports are missed, or a serious safety breach occurs. Cap any one program at 60% of the portfolio.\"
      }
    },
    {
      \"alias\": \"scorecard\",
      \"recipe\": {
        \"kind\": \"native_card\",
        \"title\": \"Board scorecard — relative 1–5\",
        \"body\": \"PROGRAM              IMPACT   COST EFF.   RISK   ROLE\\nRiver interception       5          5          M     Volume\\nGhost gear               4          3          M–H   Ecology\\nCoastal + recycling      4          4          M     Durability\\n\\nPORTFOLIO TESTS\\n✓ No single-method bet\\n✓ Independent measurement possible\\n✓ Geographic and operating-risk spread\\n✓ Every award has an exit trigger\"
      }
    },
    {
      \"alias\": \"week\",
      \"recipe\": {
        \"kind\": \"native_card\",
        \"title\": \"First week — exactly three actions\",
        \"body\": \"1  MON–TUE • Lock the mandate\\nApprove the 45/30/25 mix, cost ceilings, 90-day triggers, and one accountable portfolio owner.\\n\\n2  WED • Issue a structured RFP\\nRequire site evidence, permits, 12-month operating plan, monthly tonnage, unit-cost model, safety, and end-destination proof.\\n\\n3  THU–FRI • Stand up measurement\\nAppoint an independent verifier; publish the metric dictionary and schedule baseline checks before contracting.\"
      }
    },
    {
      \"alias\": \"debate\",
      \"recipe\": {
        \"kind\": \"native_card\",
        \"title\": \"Three questions for board debate\",
        \"body\": \"01  Is the primary objective maximum tonnes, or ecological harm avoided?\\n\\n02  Will we accept medium–high logistics risk to keep ghost gear at 30%?\\n\\n03  Should local-job and worker-safety standards be hard gates even if unit cost rises up to 10%?\\n\\nDECISION ASK\\nApprove the mix and gates now; authorize management to select operators within them.\"
      }
    },
    {
      \"alias\": \"assumptions\",
      \"recipe\": {
        \"kind\": \"native_card\",
        \"title\": \"Assumptions + measurement contract\",
        \"body\": \"WORKING ESTIMATES, NOT VENDOR BIDS\\nRanges are portfolio-planning assumptions for a 12-month deployment and must be replaced by comparable proposals.\\n\\nCOUNT ONE METRIC\\nVerified metric tonnes prevented or recovered; record wet/dry basis and exclude duplicate handoffs.\\n\\nREPORT MONTHLY\\nSpend • tonnes • cost/tonne • uptime • safety events • destination evidence.\\n\\nREVIEW AT DAYS 30 / 90 / 180\\nBoard sees exceptions, forecast, and any reallocation decision.\"
      }
    }
  ],
  \"connections\": [],
  \"layout\": {
    \"kind\": \"grid\",
    \"anchor\": {\"alias\": \"title\"},
    \"members\": [\"river\", \"gear\", \"community\", \"mix\", \"rules\", \"scorecard\", \"week\", \"debate\", \"assumptions\"],
    \"columns\": 3,
    \"column_gap\": 48,
    \"row_gap\": 48,
    \"align\": \"start\",
    \"placement\": {\"clearance\": 72, \"preferred_directions\": [\"below\"]}
  }
}
JSON"

